// สแกนหา port TCP ที่เปิดอยู่บน PLC (ใช้เวลาประมาณ 1-3 นาที)
const HOST = "192.168.0.101";
const FROM = 1, TO = 20000;           // ช่วง port ที่สแกน
const EXTRA = [44818, 48898, 61440];  // port อื่นที่พบบ่อยในโรงงาน
const PAR = 200, TMO = 700;

const ports = [];
for (let p = FROM; p <= TO; p++) ports.push(p);
EXTRA.forEach(p => { if (p > TO) ports.push(p); });

const open = [], refused = [];
let timeout = 0, idx = 0, done = 0;
const t0 = Date.now();
node.status({ fill: "blue", shape: "ring", text: "เริ่มสแกน " + HOST });

function probe(port) {
    return new Promise(res => {
        const s = new net.Socket(); let fin = false;
        const end = r => { if (fin) return; fin = true; s.destroy(); res(r); };
        s.setTimeout(TMO);
        s.once("connect", () => end("open"));
        s.once("timeout", () => end("timeout"));
        s.once("error", e => end(e.code === "ECONNREFUSED" ? "refused" : "timeout"));
        s.connect(port, HOST);
    });
}
async function worker() {
    while (idx < ports.length) {
        const p = ports[idx++];
        const r = await probe(p);
        if (r === "open") open.push(p); else if (r === "refused") refused.push(p); else timeout++;
        if (++done % 500 === 0) node.status({ fill: "blue", shape: "ring", text: done + "/" + ports.length + " | open: " + (open.join(",") || "-") });
    }
}
(async () => {
    await Promise.all(Array.from({ length: PAR }, worker));
    open.sort((a, b) => a - b);
    const sec = Math.round((Date.now() - t0) / 1000);
    node.status({ fill: open.length ? "green" : "red", shape: "dot", text: "OPEN: " + (open.join(", ") || "ไม่มี") + " (" + sec + "s)" });
    node.send({ topic: "Port scan " + HOST, payload: {
        host: HOST, range: FROM + "-" + TO, open: open,
        refused: refused.length, noReply: timeout, seconds: sec,
        hint: open.length ? "ส่งรายการ open ให้ตรวจว่าเป็น SLMP/Modbus หรือไม่"
            : (refused.length ? "PLC ตอบปฏิเสธ (RST) แต่ไม่มี port ที่เปิด -> ยังไม่ได้ตั้ง SLMP/Modbus ใน GX Works3"
                              : "PLC ไม่ตอบทุก port (ทิ้งแพ็กเก็ตเงียบ) -> ยังไม่ได้ตั้ง SLMP/Modbus ใน GX Works3 หรือมี firewall")
    }});
})();
return null;
